export interface BannerSlide {
  id: number;
  type: 'video' | 'image';
  src: string;
  title: string;
  description: string;
  callLink: string;
  waText: string;
}

export interface TaxiRoute {
  route: string;
  category: string;
  ridesCount: string;
}

export interface PackageData {
  id: number;
  title: string;
  images: string[];
  badge?: string;
  location: string;
  locationLink: string;
  duration: string;
  price: string;
  detailsLink: string;
  experienceActivities?: string[];
  inclusionDetails?: string[];
}

export interface ServiceFeature {
  id: number;
  iconSvg: string;
  title: string;
  description: string;
}

export interface DestinationData {
  id: number;
  title: string;
  image: string;
  toursCount: string;
  link: string;
}

export interface SmartService {
  id: number;
  title: string;
  iconSvg: string;
  link: string;
}

export interface BlogData {
  id: number;
  title: string;
  image: string;
  date: {
    day: string;
    month: string;
  };
  location: string;
  locationLink: string;
  detailsLink: string;
}

export interface TestimonialData {
  id: number;
  title: string;
  text: string;
  rating: number; // e.g. 5 or 4.5
  ratingType: 'circle' | 'trustpilot';
  authorName: string;
  authorRole: string;
  authorImage: string;
}

export interface CounterData {
  id: number;
  number: string;
  suffix: string;
  title: string;
  iconColor: 'yellow' | 'orange' | 'green' | 'default';
  iconSvg: string;
}

